// CRITICAL: set autoRaf:false \u2014 Lenis v1.1+ defaults autoRaf:true.
// Without it, Lenis runs its own RAF loop AND GSAP fires it again \u2014
// double-firing breaks smooth scroll and desynchronises ScrollTrigger.
import Lenis from 'lenis';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

const lenis = new Lenis({
  autoRaf: false,       // GSAP ticker is the RAF driver
  duration: 1.18,
  lerp: 0.12,
  smoothWheel: true,
  wheelMultiplier: 0.92,
  touchMultiplier: 1.8,
});

